using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _httpClient;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClient = httpClientFactory.CreateClient("WeatherApi");
    }

    [McpServerTool(Name = "get_weather")]
    [Description("Gets current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";
        var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("current_weather", out var weather))
        {
            var temp = weather.GetProperty("temperature").GetDouble();
            var windSpeed = weather.GetProperty("windspeed").GetDouble();
            return $"Temperature: {temp}°C, Wind: {windSpeed} km/h";
        }

        return "Unable to retrieve weather data.";
    }

    [McpServerTool(Name = "get_forecast")]
    [Description("Gets a 7-day temperature forecast for a location.")]
    public async Task<string> GetForecastAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}&daily=temperature_2m_max,temperature_2m_min&timezone=auto";
        var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);

        if (response.TryGetProperty("daily", out var daily))
        {
            return daily.GetRawText();
        }

        return "Unable to retrieve forecast data.";
    }
}

